	t.Run("unknown_library_is_404", func(t *testing.T) {
		calls := 0
		h := New(Deps{AdminToken: adminToken, Store: st, EnrichPreview: func(context.Context, int64, string) (EnrichPreview, error) {
			calls++
			return EnrichPreview{}, nil
		}})
		resp := doRequest(t, h, http.MethodGet, "/api/v1/libraries/99999/enrich/preview?plugin_id=shikimori", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusNotFound {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusNotFound)
		}
		if calls != 0 {
			t.Fatalf("closure called %d times, want 0", calls)
		}
	})

	t.Run("happy_path_passes_through_the_closure_value", func(t *testing.T) {
		var gotID int64
		var gotPlugin string
		want := EnrichPreview{
			PluginID: "shikimori",
			Matches:  7,
			Pending:  2,
			Cooling:  1,
			Versions: map[string]int{"1.0.0": 5, "2.0.0": 2},
		}
		h := New(Deps{AdminToken: adminToken, Store: st, EnrichPreview: func(_ context.Context, libraryID int64, pluginID string) (EnrichPreview, error) {
			gotID, gotPlugin = libraryID, pluginID
			return want, nil
		}})
		resp := doRequest(t, h, http.MethodGet, libPath+"?plugin_id=shikimori", "", adminToken)
		defer resp.Body.Close()
		if resp.StatusCode != http.StatusOK {
			t.Fatalf("status = %d, want %d", resp.StatusCode, http.StatusOK)
		}
		if gotID != libID || gotPlugin != "shikimori" {
			t.Fatalf("closure args = (%d, %q), want (%d, shikimori)", gotID, gotPlugin, libID)
		}
		var got EnrichPreview
		if err := json.NewDecoder(resp.Body).Decode(&got); err != nil {
			t.Fatalf("decode body: %v", err)
		}
		if got.PluginID != want.PluginID || got.Matches != want.Matches || got.Pending != want.Pending || got.Cooling != want.Cooling {
			t.Fatalf("preview = %+v, want %+v", got, want)
		}
		if !reflect.DeepEqual(got.Versions, want.Versions) {
			t.Fatalf("versions = %v, want the closure histogram verbatim %v", got.Versions, want.Versions)
		}
	})
